An interviewer asks you to sketch how `useState` works using an array and a cursor. Here is a first attempt. What does the last line log?

```js
let hooks = [];
let cursor = 0;

function useState(initial) {
  if (hooks[cursor] === undefined) hooks[cursor] = initial;
  const value = hooks[cursor];
  const setState = (next) => { hooks[cursor] = next; };
  cursor++;
  return [value, setState];
}

function App() {
  const [a, setA] = useState('a');
  const [b, setB] = useState('b');
  return { a, b, setA, setB };
}

cursor = 0; let r = App();
r.setA('A');
cursor = 0; r = App();
console.log(r.a, r.b);
```

